import os
os.environ['OPENBLAS_NUM_THREADS']='1'
os.environ['OMP_NUM_THREADS']='1'
import pandas as pd, numpy as np, time, warnings, pickle
from sklearn.model_selection import KFold
from sklearn.metrics import mean_squared_error,mean_absolute_error,r2_score
from sklearn.preprocessing import StandardScaler
from sklearn.ensemble import ExtraTreesRegressor,RandomForestRegressor,HistGradientBoostingRegressor
from sklearn.neighbors import KNeighborsRegressor
from sklearn.gaussian_process import GaussianProcessRegressor
from sklearn.gaussian_process.kernels import Matern, WhiteKernel, ConstantKernel, RBF
from catboost import CatBoostRegressor
warnings.filterwarnings('ignore')
tr=pd.read_csv('/work/b3_htsteel_toughness_pareto_train.csv'); po=pd.read_csv('/work/b3_htsteel_toughness_pareto_pool.csv')
cols=tr.columns[:-2];cols=cols[tr[cols].nunique()>1]
X=tr[cols].copy();P=po[cols].copy();y=tr.iloc[:,-2:].values
cv=list(KFold(5,shuffle=True,random_state=42).split(X))
res={}; models={}
for name in ['knn1','knn3','knn5','et','rf','cb4','cb6','cb4log','gp','gplog']:
    t=time.time(); xx=X.copy(); pp=P.copy()
    if name.startswith('knn') or name.startswith('gp'):
        for c in cols:
            if 'duration' in c or 'cooling' in c:
                xx[c]=np.log1p(xx[c]); pp[c]=np.log1p(pp[c])
        scaler=StandardScaler().fit(xx);xx=scaler.transform(xx);pp=scaler.transform(pp)
    else:xx=xx.values;pp=pp.values
    preds=np.zeros_like(y); final=np.zeros((len(P),2)); fitted=[]
    for j in range(2):
        yy=y[:,j].copy()
        if 'log' in name: yy=np.log(yy)
        for k,(a,b) in enumerate(cv+[(np.arange(len(X)),np.arange(len(X)))]):
            if name.startswith('knn'):m=KNeighborsRegressor(n_neighbors=int(name[3:]),weights='distance')
            elif name=='et':m=ExtraTreesRegressor(n_estimators=600,max_features=1.,min_samples_leaf=1,n_jobs=4,random_state=42)
            elif name=='rf':m=RandomForestRegressor(n_estimators=600,max_features=.8,min_samples_leaf=1,n_jobs=4,random_state=42)
            elif name.startswith('cb'):m=CatBoostRegressor(iterations=1600,depth=int(name[2]),learning_rate=.035,l2_leaf_reg=3,loss_function='RMSE',verbose=False,thread_count=4,random_seed=42,allow_writing_files=False)
            elif name.startswith('gp'):
                kernel=ConstantKernel(1,(.01,100))*Matern(np.ones(xx.shape[1]),(.05,100),nu=2.5)+WhiteKernel(.03,(.0001,1))
                m=GaussianProcessRegressor(kernel=kernel,normalize_y=True,n_restarts_optimizer=0,random_state=42)
            m.fit(xx[a], yy[a]); pred=m.predict(xx[b] if k<5 else pp)
            if 'log' in name:pred=np.exp(pred)
            if k<5:preds[b,j]=pred
            else:
                final[:,j]=pred; fitted.append(m)
                if name.startswith('gp'):print(name,j,'kernel',m.kernel_,flush=True)
    print(name,'time',round(time.time()-t), 'RMSE',np.sqrt(((preds-y)**2).mean(0)).round(1),'MAE',np.abs(preds-y).mean(0).round(1),'R2',r2_score(y,preds,multioutput='raw_values').round(3),flush=True)
    res[name]={'oof':preds,'pool':final};models[name]=fitted
    with open('/tmp/steel_models.pkl','wb') as f:pickle.dump((res,models),f)
    p=final
    front=[i for i in range(len(p)) if not np.any(np.all(p>=p[i],axis=1)&np.any(p>p[i],axis=1))]
    print([(po.candidate_id[i],np.round(p[i],1).tolist()) for i in sorted(front,key=lambda i:p[i,0])],flush=True)

